```

## Concept Detection

```python
CONCEPT_KEYWORDS = {
    'auth': ['auth', 'login', 'session', 'jwt', 'token', 'password'],
    'api': ['route', 'handler', 'endpoint', 'controller', 'request', 'response'],
    'database': ['db', 'database', 'query', 'model', 'schema', 'migration'],
    'ui': ['component', 'render', 'view', 'page', 'layout', 'style'],
    'validation': ['validate', 'schema', 'check', 'sanitize'],
    'testing': ['test', 'spec', 'mock', 'fixture'],
}

def detect_concepts(files: List[FileEntry]) -> List[str]:
    '''Detect domain concepts from file names and exports.'''
    found = set()
    for file in files:
        text = file.path.lower() + ' ' + ' '.join(e.name.lower() for e in file.exports)
        for concept, keywords in CONCEPT_KEYWORDS.items():
            if any(kw in text for kw in keywords):
                found.add(concept)
    return sorted(found)
```

## API Signature Formatting

```python
def format_api_signature(chunk: ChunkEntry, language: str) -> str:
    '''Format chunk as displayable API signature.'''
    sig = chunk.signature
    # Truncate very long signatures
    if len(sig) > 120:
        sig = sig[:117] + '...'
    return sig
