# Template Engine for AGENTS.md

## Goal
Create a simple, zero-dependency template engine for generating AGENTS.md files.

## Design Decisions

### Why Not Jinja2?
- Adds a dependency
- We only need simple substitution
- Full templating power is overkill

### Template Syntax
Simple variable substitution:
```
{{ variable_name }}
{{ nested.property }}
```

Conditionals:
```
{% if has_cycles %}
## ⚠️ Circular Dependencies
{% endif %}
```

Loops:
```
{% for file in key_files %}
- {{ file.path }} ({{ file.centrality }})
{% endfor %}
```

## Implementation

```python
import re
from typing import Any, Dict

class SimpleTemplate:
    '''Zero-dependency template engine for AGENTS.md generation.'''

    VAR_PATTERN = re.compile(r'\{\{\s*([\w.]+)\s*\}\}')
    IF_PATTERN = re.compile(r'\{%\s*if\s+([\w.]+)\s*%\}(.+?)\{%\s*endif\s*%\}', re.DOTALL)
    FOR_PATTERN = re.compile(r'\{%\s*for\s+(\w+)\s+in\s+([\w.]+)\s*%\}(.+?)\{%\s*endfor\s*%\}', re.DOTALL)

    def __init__(self, template: str):
        self.template = template

    def render(self, context: Dict[str, Any]) -> str:
        result = self.template

        # Process conditionals first
        result = self._process_conditionals(result, context)

        # Process loops
        result = self._process_loops(result, context)

        # Substitute variables
        result = self._substitute_vars(result, context)

        return result

    def _get_value(self, key: str, context: Dict[str, Any]) -> Any:
        '''Get nested value from context using dot notation.'''
        parts = key.split('.')
        value = context
        for part in parts:
            if isinstance(value, dict):
                value = value.get(part)
            else:
                value = getattr(value, part, None)
            if value is None:
                return ''
        return value

    def _substitute_vars(self, text: str, context: Dict[str, Any]) -> str:
        def replace(match):
            key = match.group(1)
            value = self._get_value(key, context)
            return str(value) if value is not None else ''
        return self.VAR_PATTERN.sub(replace, text)

    def _process_conditionals(self, text: str, context: Dict[str, Any]) -> str:
        def replace(match):
            condition = match.group(1)
            body = match.group(2)
            value = self._get_value(condition, context)
            if value:
                return body
            return ''
        return self.IF_PATTERN.sub(replace, text)

    def _process_loops(self, text: str, context: Dict[str, Any]) -> str:
        def replace(match):
            var_name = match.group(1)
            collection_key = match.group(2)
            body = match.group(3)

            collection = self._get_value(collection_key, context)
            if not collection:
                return ''

            result = []
            for item in collection:
                item_context = {**context, var_name: item}
                result.append(self._substitute_vars(body, item_context))
            return ''.join(result)

        return self.FOR_PATTERN.sub(replace, text)
```

## Template Loading

```python
def load_template(name: str) -> SimpleTemplate:
    '''Load template from embedded strings or external file.'''
    templates = {
        'root': ROOT_TEMPLATE,
        'directory': DIRECTORY_TEMPLATE,
        'module': MODULE_TEMPLATE,
    }

    if name in templates:
        return SimpleTemplate(templates[name])

    # Try loading from file
    template_path = Path(__file__).parent / 'templates' / f'{name}.md'
    if template_path.exists():
        return SimpleTemplate(template_path.read_text())

    raise ValueError(f'Unknown template: {name}')
```

